    get: jest.fn(),
  },
}));

const mockStore = configureStore({
  reducer: {
    dataMask: () => ({}),
  },
});

const baseMockProps = {
  formData: {
    datasource: 'test_datasource',
    viz_type: 'deck_multi',
    deck_slices: [1, 2],
    autozoom: false,
    mapbox_style: 'mapbox://styles/mapbox/light-v9',
  },
