            datasource: 'test_datasource',
          },
        },
      ],
      features: {
        deck_scatter: [{ position: [0, 0] }],
        deck_polygon: [
          {
            polygon: [
              [1, 1],
              [2, 2],
            ],
          },
        ],
        deck_path: [],
        deck_grid: [],
        deck_contour: [],
        deck_heatmap: [],
        deck_hex: [],
        deck_arc: [],
        deck_geojson: [],
        deck_screengrid: [],
      },
      mapboxApiKey: 'test-key',
    },
  },
  setControlValue: jest.fn(),
  viewport: { longitude: 0, latitude: 0, zoom: 1 },
