        {
          Milton: 10,
          'San Francisco': 2,
          'New York': 7,
          Boston: 2,
          __timestamp: 600516000000,
        },
      ],
    },
  ];

  const getChartProps = (formData: Partial<SqlaFormData>) =>
    new ChartProps({
      ...chartPropsConfig,
      formData: { ...formData },
      queriesData: legendSortData,
    });

  it('sort legend by data', () => {
    const chartProps = getChartProps({
      legendSort: null,
      sortSeriesType: 'min',
      sortSeriesAscending: true,
    });
    const transformed = transformProps(
      chartProps as EchartsTimeseriesChartProps,
    );

    expect((transformed.echartOptions.legend as any).data).toEqual([
      'San Francisco',
      'Boston',
      'New York',
      'Milton',
    ]);
  });

  it('sort legend by label ascending', () => {
    const chartProps = getChartProps({
      legendSort: 'asc',
      sortSeriesType: 'min',
      sortSeriesAscending: true,
    });
    const transformed = transformProps(
      chartProps as EchartsTimeseriesChartProps,
    );

    expect((transformed.echartOptions.legend as any).data).toEqual([
      'Boston',
      'Milton',
      'New York',
      'San Francisco',
    ]);
  });

  it('sort legend by label descending', () => {
    const chartProps = getChartProps({
      legendSort: 'desc',
      sortSeriesType: 'min',
      sortSeriesAscending: true,
    });
    const transformed = transformProps(
      chartProps as EchartsTimeseriesChartProps,
    );

    expect((transformed.echartOptions.legend as any).data).toEqual([
      'San Francisco',
      'New York',
      'Milton',
      'Boston',
    ]);
  });
});

