test('EchartsTimeseries AUTO mode should use neutral formatting for mixed currencies', () => {
  const chartProps = new ChartProps<SqlaFormData>({
    ...chartPropsConfig,
    formData: {
      ...formData,
      metrics: ['sum__num'],
      currencyFormat: { symbol: 'AUTO', symbolPosition: 'prefix' },
