        data: [
          {
            'San Francisco': 1000,
            __timestamp: 599616000000,
            currency_code: 'USD',
          },
          {
            'San Francisco': 2000,
            __timestamp: 599916000000,
            currency_code: 'EUR',
          },
        ],
      },
    ],
  });

  const transformed = transformProps(chartProps as EchartsTimeseriesChartProps);

