        ],
        hooks: { setDataMask },
        filterState: { selectedFilters: {} },
        datasource: {
          verboseMap: {},
          columnFormats: {},
          currencyCodeColumn: 'currency',
        },
        theme: supersetTheme,
      });

      const result = transformProps(staticChartProps);
      expect(result.currencyFormat).toEqual({
        symbol: 'EUR',
        symbolPosition: 'suffix',
      });
    });
  });
});

