};

fetchMock.get(/\/api\/v1\/dataset\/\?q=.*/, {
  body: mockDatasourceResponse,
  status: 200,
});

const mockUser: UserWithPermissionsAndRoles = {
  createdOn: '2021-04-27T18:12:38.952304',
  email: 'admin',
  firstName: 'admin',
  isActive: true,
  lastName: 'admin',
  permissions: {},
  roles: { Admin: Array(173) },
  userId: 1,
  username: 'admin',
