          border-bottom-color: ${theme.colorPrimary} !important;
          & .ant-tabs-tab-btn {
            font-weight: ${theme.fontWeightStrong};
            color: ${theme.colorTextBase} !important;
            text-shadow: none !important;
          }
        }
      }
