// Table charts don't support matrixify feature
const MATRIXIFY_INCOMPATIBLE_CHARTS = new Set([
  VizType.Table,
  VizType.TableAgGrid,
  VizType.PivotTable,
  VizType.TimeTable,
  VizType.TimePivot,
