  CRONTAB_ERROR_TEXT: t('crontab'),
  WORKING_TIMEOUT_ERROR_TEXT: t('working timeout'),
  RECIPIENTS_ERROR_TEXT: t('recipients'),
  EMAIL_SUBJECT_ERROR_TEXT: t('email subject'),
  EMAIL_VALIDATION_ERROR_TEXT: t('invalid email'),
