jest.mock('./AceEditorProvider', () => ({
  __esModule: true,
  default: ({ id, value, language }: EditorProps) => (
    <div data-test="ace-editor-provider">
      <span data-test="ace-editor-id">{id}</span>
      <span data-test="ace-editor-value">{value}</span>
