+  for (const source of SOURCES.filter(s => s.enabled)) {
+    const dir = path.join(FRONTEND_DIR, source.path);
+    const sourceFiles = walkDir(dir, []);
+    // Attach source config to each file
+    for (const file of sourceFiles) {
