+    let key, valueStr;
+    if (propMatch) {
+      key = propMatch[1];
+      valueStr = propMatch[2];
+    } else {
+      // Value is on the next line
+      key = keyOnlyMatch[1];
+      const nextLine = i + 1 < lines.length ? lines[i + 1].trim().replace(/,\s*$/, '') : '';
+      if (!nextLine) continue;
+      valueStr = nextLine;
+      i++; // Skip the next line since we consumed it
