+    // Parse the value
+    // Double-quoted string (handles apostrophes inside)
+    const doubleQuoteMatch = valueStr.match(/^"([^"]*)"$/);
+    if (doubleQuoteMatch) {
+      args[key] = doubleQuoteMatch[1];
+      continue;
+    }
