+  if (remaining.startsWith("'")) {
+    let i = 1;
+    while (i < remaining.length) {
+      if (remaining[i] === "'" && remaining[i - 1] !== '\\') {
+        return remaining.slice(1, i);
+      }
+      i++;
+    }
+  }
+
+  // Double-quoted string
+  if (remaining.startsWith('"')) {
+    let i = 1;
+    while (i < remaining.length) {
+      if (remaining[i] === '"' && remaining[i - 1] !== '\\') {
+        return remaining.slice(1, i);
+      }
+      i++;
+    }
+  }
+
+  // Template literal
+  if (remaining.startsWith('`')) {
+    let i = 1;
+    while (i < remaining.length) {
+      if (remaining[i] === '`' && remaining[i - 1] !== '\\') {
+        return remaining.slice(1, i).replace(/\s+/g, ' ').trim();
