+  for (let i = startIndex; i < content.length; i++) {
+    if (content[i] === '{') {
+      if (depth === 0) start = i + 1;
+      depth++;
+    } else if (content[i] === '}') {
+      depth--;
+      if (depth === 0) {
+        return content.slice(start, i);
+      }
+    }
+  }
+  return null;
+}
