type ButtonSize = Pick<ButtonProps, 'buttonSize'>;
type ButtonSizeValue = ButtonSize[keyof ButtonSize];

export default {
  title: 'Components/Button',
  component: Button,
  includeStories: ['ButtonGallery', 'InteractiveButton'],
};

const buttonStyles: ButtonStyleValue[] = [
  'primary',
  'secondary',
  'dashed',
  'danger',
  'link',
];

const buttonSizes: ButtonSizeValue[] = ['xsmall', 'small', 'default'];

export const STYLES = {
  label: 'styles',
  options: buttonStyles,
  defaultValue: undefined,
};

export const SIZES = {
  label: 'sizes',
  options: buttonSizes,
  defaultValue: undefined,
};

const TARGETS = {
  label: 'target',
  options: {
    blank: '_blank',
    none: null,
  },
  defaultValue: null,
};

const HREFS = {
  label: 'href',
  options: {
    superset: 'https://superset.apache.org/',
    none: null,
  },
  defaultValue: null,
};

export const ButtonGallery = () => (
  <>
    {SIZES.options.map(size => (
      <div key={size} style={{ marginBottom: 40 }}>
        <h4>{size}</h4>
        {Object.values(STYLES.options).map(style => (
          <Button
            buttonStyle={style}
            buttonSize={size}
            onClick={() => true}
            key={`${style}_${size}`}
            style={{ marginRight: 20, marginBottom: 10 }}
          >
            {style}
          </Button>
        ))}
      </div>
    ))}
  </>
);

