InteractiveTimer.argTypes = {
  isRunning: {
    control: 'boolean',
    description:
      'Whether the timer is actively counting. Toggle to start/stop.',
  },
  status: {
    control: { type: 'select' },
    options: [
      'success',
      'warning',
      'danger',
      'info',
      'default',
      'primary',
      'secondary',
