    <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
      {['success', 'warning', 'danger', 'info', 'default', 'primary', 'secondary'].map(status => (
        <div key={status} style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
