    const queryEditorId = query.sqlEditorId ?? query.id;
    const sync = isFeatureEnabled(FeatureFlag.SqllabBackendPersistence)
      ? SupersetClient.delete({
          endpoint: encodeURI(
            `/tabstateview/${queryEditorId}/query/${query.id}`,
