                  const selectedIndex = selectedIds.indexOf(o.id);
                  const indexLabel =
                    selectedIndex !== -1 ? ` [${selectedIndex + 1}]` : '';

                  return {
                    value: o.id,
                    label: `${o.slice_name}${indexLabel}`,
                  };
                });
              },
            },
          },
          null,
        ],
      ],
    },
    {
      label: t('Query'),
      expanded: true,
      controlSetRows: [['adhoc_filters']],
    },
  ],
};

