test('should handle controls with complex structure', async () => {
  const controlPanelConfig = {
    controlPanelSections: [
      {
        controlSetRows: [
          [
            {
              config: {
                name: 'nested_control',
                renderTrigger: true,
              },
            },
          ],
          [
            {
              name: 'direct_control',
              config: {
                renderTrigger: true,
