import { ViewContribution } from 'src/SqlLab/contributions';
import MenuListExtension from 'src/components/MenuListExtension';
import { useExtensionsContext } from 'src/extensions/ExtensionsContext';
import ExtensionsManager from 'src/extensions/ExtensionsManager';
import useQueryEditor from 'src/SqlLab/hooks/useQueryEditor';
import useLogAction from 'src/logger/useLogAction';
import { LOG_ACTIONS_SQLLAB_SWITCH_SOUTH_PANE_TAB } from 'src/logger/LogUtils';
import QueryHistory from '../QueryHistory';
import {
  STATUS_OPTIONS,
  STATE_TYPE_MAP,
  STATUS_OPTIONS_LOCALIZED,
} from '../../constants';
import Results from './Results';
import TablePreview from '../TablePreview';

/*
    editorQueries are queries executed by users passed from SqlEditor component
    dataPreviewQueries are all queries executed for preview of table data (from SqlEditorLeft)
*/
export interface SouthPaneProps {
  queryEditorId: string;
  latestQueryId?: string;
  displayLimit: number;
  defaultQueryLimit: number;
}

const TABS_KEYS = {
  RESULTS: 'Results',
  HISTORY: 'History',
};

const StyledPane = styled.div`
  width: 100%;
  height: 100%;
  .ant-tabs .ant-tabs-content-holder {
    overflow: visible;
  }
  .SouthPaneTabs {
    height: 100%;
    display: flex;
    flex-direction: column;
    .scrollable {
      overflow-y: auto;
    }
  }
  .ant-tabs-extra-content {
    margin: 0 ${({ theme }) => theme.sizeUnit * 4}px
      ${({ theme }) => theme.sizeUnit * 2}px;
  }
  .ant-tabs-tabpane {
    .scrollable {
      overflow-y: auto;
    }
  }
  .tab-content {
    .alert {
      margin-top: ${({ theme }) => theme.sizeUnit * 2}px;
    }

    button.fetch {
      margin-top: ${({ theme }) => theme.sizeUnit * 2}px;
    }
  }
`;

const SouthPane = ({
  queryEditorId,
  latestQueryId,
  displayLimit,
  defaultQueryLimit,
}: SouthPaneProps) => {
  const { id, tabViewId } = useQueryEditor(queryEditorId, ['tabViewId']);
  const editorId = tabViewId ?? id;
  const theme = useTheme();
  const dispatch = useDispatch();
  const contributions =
    ExtensionsManager.getInstance().getViewContributions(
      ViewContribution.Panels,
    ) || [];
  const { getView } = useExtensionsContext();
  const { offline, tables } = useSelector(
    ({ sqlLab: { offline, tables } }: SqlLabRootState) => ({
      offline,
      tables,
    }),
    shallowEqual,
  );
  const activeSouthPaneTab =
    useSelector<SqlLabRootState, string>(
      state => state.sqlLab.activeSouthPaneTab as string,
    ) ?? 'Results';

  const pinnedTables = useMemo(
    () => tables.filter(({ queryEditorId: qeId }) => String(editorId) === qeId),
    [editorId, tables],
  );
  const pinnedTableKeys = useMemo(
    () =>
      Object.fromEntries(
        pinnedTables.map(({ id, dbId, catalog, schema, name }) => [
          id,
          [dbId, catalog, schema, name].join(':'),
        ]),
      ),
    [pinnedTables],
  );
  const southPaneRef = createRef<HTMLDivElement>();
  const logAction = useLogAction({ sqlEditorId: queryEditorId });
  const switchTab = (id: string) => {
    dispatch(setActiveSouthPaneTab(id));
    logAction(LOG_ACTIONS_SQLLAB_SWITCH_SOUTH_PANE_TAB, { tab: id });
  };
  const removeTable = useCallback(
    (key, action) => {
      if (action === 'remove') {
        const table = pinnedTables.find(
          ({ dbId, catalog, schema, name }) =>
            [dbId, catalog, schema, name].join(':') === key,
        );
        if (table) {
          dispatch(removeTables([table]));
        }
      }
    },
    [dispatch, pinnedTables],
  );

  if (offline) {
    return (
      <Label type={STATE_TYPE_MAP[STATUS_OPTIONS.offline]}>
        {STATUS_OPTIONS_LOCALIZED.offline}
      </Label>
    );
  }

  const tabItems = [
    {
      key: TABS_KEYS.RESULTS,
      label: t('Results'),
      children: (
        <Results
          latestQueryId={latestQueryId}
          displayLimit={displayLimit}
          defaultQueryLimit={defaultQueryLimit}
        />
      ),
      closable: false,
    },
    {
      key: TABS_KEYS.HISTORY,
      label: t('Query history'),
      children: (
        <QueryHistory
          queryEditorId={queryEditorId}
          displayLimit={displayLimit}
          latestQueryId={latestQueryId}
        />
      ),
      closable: false,
    },
    ...pinnedTables.map(({ id, dbId, catalog, schema, name }) => ({
      key: pinnedTableKeys[id],
      label: (
        <>
          <Icons.InsertRowAboveOutlined
            iconSize="l"
            css={css`
              margin-bottom: ${theme.sizeUnit * 0.5}px;
              margin-right: ${theme.sizeUnit}px;
            `}
          />
          {`${schema}.${decodeURIComponent(name)}`}
        </>
      ),
      children: (
        <TablePreview
          dbId={dbId}
          catalog={catalog}
          schema={schema}
          tableName={name}
        />
      ),
    })),
    ...contributions.map(contribution => ({
      key: contribution.id,
      label: contribution.name,
      children: getView(contribution.id),
      forceRender: true,
      closable: false,
    })),
  ];

  return (
    <StyledPane data-test="south-pane" className="SouthPane" ref={southPaneRef}>
      <Tabs
        tabBarExtraContent={{
          right: (
            <Flex
              css={css`
                padding: 8px;
              `}
            >
              <MenuListExtension viewId={ViewContribution.Panels} primary />
              <MenuListExtension viewId={ViewContribution.Panels} secondary />
            </Flex>
          ),
        }}
        type="editable-card"
        activeKey={pinnedTableKeys[activeSouthPaneTab] || activeSouthPaneTab}
        className="SouthPaneTabs"
        onChange={switchTab}
        id={nanoid(11)}
        animated={false}
        onEdit={removeTable}
        hideAdd
        items={tabItems}
      />
    </StyledPane>
  );
};

export default SouthPane;

