        .attr('text-anchor', function () {
          switch (options.label.align) {
            case 'start':
            case 'left':
              return 'start';
            case 'end':
            case 'right':
              return 'end';
            default:
              return 'middle';
          }
        })
        .attr('dominant-baseline', function () {
          return self.verticalDomainLabel ? 'middle' : 'top';
        })
        .text(function (d) {
          return self.formatDate(new Date(d), options.domainLabelFormat);
