  oldTable?: Table;
  newTable?: Table;
  // Database related
  databases?: Database[] | Record<string, Database>;
  dbId?: number;
  // State and config
  sqlLabInitialState?: SqlLabRootState['sqlLab'];
  sql?: string | null;
  name?: string;
  catalog?: string | null;
  schema?: string | null;
