  align-items: center;
`;

const SortSeqLabel = styled.span`
  position: absolute;
  right: 0;
`;

const HeaderAction = styled.div`
  display: none;
  position: absolute;
  right: 0;
  &.main {
    flex-direction: row;
    justify-content: center;
