import DashboardWrapper from './DashboardWrapper';

// @z-index-above-dashboard-charts + 1 = 11
const FiltersPanel = styled.div<{ width: number; hidden: boolean }>`
  background-color: ${({ theme }) => theme.colorBgContainer};
  grid-column: 1;
  grid-row: 1 / span 2;
  z-index: 11;
