            css={css`
              vertical-align: sub;
            `}
          />
        </CloseContainer>
      )}
      <Label data-test="control-label">{children}</Label>
      {!!multiValueWarningMessage && (
        <StyledInfoTooltip
          type="warning"
          placement="top"
