function RoleListAddModal({
  show,
  onHide,
  onSave,
  permissions,
}: RoleListAddModalProps) {
  const { addDangerToast, addSuccessToast } = useToasts();
  const handleFormSubmit = async (values: RoleForm) => {
    try {
      const { json: roleResponse } = await createRole(values.roleName);

