      onSave={onSave}
      formSubmitHandler={handleFormSubmit}
      requiredFields={['roleName']}
      initialValues={{}}
    >
      <>
        <RoleNameField />
        <PermissionsField permissions={permissions} />
      </>
    </FormModal>
  );
}

