      expanded: true,
      controlSetRows: [
        [
          {
            name: 'sortAscending',
            config: {
              type: 'CheckboxControl',
              renderTrigger: true,
              label: t('Sort ascending'),
              default: sortAscending,
              description: t('Check for sorting ascending'),
            },
          },
        ],
        [
          {
            name: 'creatable',
            config: {
              type: 'CheckboxControl',
              label: t('Allow creation of new values'),
              default: creatable,
              affectsDataMask: true,
              renderTrigger: true,
            },
