import { useMemo } from 'react';
import { t } from '@apache-superset/core';
import { css } from '@apache-superset/core/ui';
import SubMenu, { SubMenuProps } from 'src/features/home/SubMenu';
import { useListViewResource } from 'src/views/CRUD/hooks';
import { useToasts } from 'src/components/MessageToasts/withToasts';
import {
  ListView,
  ListViewFilterOperator,
  type ListViewFilter,
} from 'src/components/ListView';
import { Typography } from '@superset-ui/core/components';
import { fetchUserOptions } from 'src/features/groups/utils';

export type ActionLogObject = {
  user: {
    username: string;
  };
  action: string;
  dttm: string | null;
  dashboard_id?: number;
  slice_id?: number;
  json?: string;
  duration_ms?: number;
  referrer?: string;
};

const PAGE_SIZE = 25;

function ActionLogList() {
  const { addDangerToast, addSuccessToast } = useToasts();
  const initialSort = [{ id: 'dttm', desc: true }];
  const subMenuButtons: SubMenuProps['buttons'] = [];

  const {
    state: {
      loading,
      resourceCount: LogsCount,
      resourceCollection: Logs,
      bulkSelectEnabled,
    },
    fetchData,
    refreshData,
    toggleBulkSelect,
  } = useListViewResource<ActionLogObject>(
    'log',
    t('Log'),
    addDangerToast,
    false,
  );
  const filters: ListViewFilter[] = useMemo(
    () => [
      {
        Header: t('Users'),
        key: 'user',
        id: 'user',
        input: 'select',
        operator: ListViewFilterOperator.RelationOneMany,
        unfilteredLabel: t('All'),
        fetchSelects: async (
          filterValue: string,
          page: number,
          pageSize: number,
        ) => fetchUserOptions(filterValue, page, pageSize, addDangerToast),
      },
      {
        Header: t('Dashboard Id'),
        key: 'dashboard_id',
        id: 'dashboard_id',
        input: 'search',
        operator: ListViewFilterOperator.Equals,
      },
      {
        Header: t('Slice Id'),
        key: 'slice_id',
        id: 'slice_id',
        input: 'search',
        operator: ListViewFilterOperator.Equals,
      },
      {
        Header: t('Action'),
        key: 'action',
        id: 'action',
        input: 'search',
        operator: ListViewFilterOperator.Contains,
      },
      {
        Header: t('JSON'),
        key: 'json',
        id: 'json',
        input: 'search',
        operator: ListViewFilterOperator.Contains,
      },
      {
        Header: t('dttm'),
        key: 'dttm',
        id: 'dttm',
        input: 'datetime_range',
        operator: ListViewFilterOperator.Between,
        dateFilterValueType: 'iso',
      },
      {
        Header: t('Referrer'),
        key: 'referrer',
        id: 'referrer',
        input: 'search',
        operator: ListViewFilterOperator.Equals,
      },
      {
        Header: t('Duration Ms'),
        key: 'duration_ms',
        id: 'duration_ms',
        input: 'search',
        operator: ListViewFilterOperator.Equals,
      },
    ],
    [],
  );

  const columns = useMemo(
    () => [
      {
        accessor: 'action',
        Header: t('Action'),
        Cell: ({
          row: {
            original: { action },
          },
        }: any) => <span>{action}</span>,
      },
      {
        accessor: 'user',
        Header: t('User'),
        Cell: ({
          row: {
            original: { user },
          },
        }: any) => <span>{user?.username}</span>,
      },

      {
        accessor: 'duration_ms',
        Header: t('Duration Ms'),

        Cell: ({
          row: {
            original: { duration_ms },
          },
        }: any) => <span>{duration_ms}</span>,
      },
      {
        accessor: 'dashboard_id',
        Header: t('Dashboard Id'),
        hidden: false,
        Cell: ({
          row: {
            original: { dashboard_id },
          },
        }: any) => <span>{dashboard_id}</span>,
      },
      {
        accessor: 'slice_id',
        Header: t('Slice Id'),
        hidden: false,
        Cell: ({
          row: {
            original: { slice_id },
          },
        }: any) => <span>{slice_id}</span>,
      },
      {
        accessor: 'json',
        Header: t('JSON'),

        Cell: ({
          row: {
            original: { json },
          },
        }: any) => (
          <Typography.Text
            css={css`
              .ant-typography-copy {
                visibility: hidden;
              }
              &:hover .ant-typography-copy {
                visibility: visible;
              }
            `}
            copyable={!!json}
            ellipsis={{
              tooltip: { styles: { root: { maxWidth: '900px' } }, title: json },
            }}
          >
            {json}
          </Typography.Text>
        ),
      },

      {
        accessor: 'referrer',
        Header: t('Referrer'),

        Cell: ({
          row: {
            original: { referrer },
          },
        }: any) => (
          <Typography.Text
            css={css`
              .ant-typography-copy {
                visibility: hidden;
              }
              &:hover .ant-typography-copy {
                visibility: visible;
              }
            `}
            copyable={!!referrer}
            ellipsis={{
              tooltip: {
                styles: { root: { maxWidth: '580px' } },
                title: referrer,
              },
            }}
          >
            {referrer}
          </Typography.Text>
        ),
      },
      {
        accessor: 'dttm',
        Header: t('Dttm'),
        Cell: ({
          row: {
            original: { dttm },
          },
        }: any) => <span>{dttm}</span>,
      },
    ],
    [],
  );

  const emptyState = {
    title: t('No Logs yet'),
    image: 'filter-results.svg',
  };

  return (
    <>
      <SubMenu name={t('Action Logs')} buttons={subMenuButtons} />
      <ListView<ActionLogObject>
        className="action-log-view"
        columns={columns}
        count={LogsCount}
        data={Logs}
        fetchData={fetchData}
        filters={filters}
        initialSort={initialSort}
        loading={loading}
        pageSize={PAGE_SIZE}
        bulkSelectEnabled={bulkSelectEnabled}
        disableBulkSelect={toggleBulkSelect}
        addDangerToast={addDangerToast}
        addSuccessToast={addSuccessToast}
        emptyState={emptyState}
        refreshData={refreshData}
      />
    </>
  );
}

export default ActionLogList;

