// Type definitions for SqlLab actions
export interface Query {
  id: string;
  dbId?: number;
  sql: string;
  sqlEditorId?: string | null;
  sqlEditorImmutableId?: string;
  tab?: string | null;
  catalog?: string | null;
  schema?: string | null;
  tempTable?: string | null;
  templateParams?: string;
  queryLimit?: number;
  runAsync?: boolean;
