                                controlsOrder.indexOf(b as ControlKey),
                            )
                            .map(key => controlItems[key].element)}
                        </>
                      ),
                    },
                  ]}
                />
              </StyledSettings>
            </>
          ),
        },
        {
          key: FilterTabs.scoping.key,
          label: FilterTabs.scoping.name,
          forceRender: true,
          children: (
            <FilterScope
