test('shows boolean only operators when subject is boolean', () => {
  const props = setup({
    adhocFilter: new AdhocFilter({
      expressionType: ExpressionTypes.Simple,
      subject: 'value',
      operatorId: undefined,
      operator: undefined,
      comparator: undefined,
      clause: undefined,
