test('sets comparator to undefined when operator is IS_NULL or IS_NOT_NULL', () => {
  const props = setup();
  const { onOperatorChange } = useSimpleTabFilterProps(
    props as unknown as Props,
  );
  [Operators.IsNull, Operators.IsNotNull].forEach(op => {
