+
+const NOOP = () => {};
+export const DEFAULT_MAX_ZOOM = 16;
+export const DEFAULT_POINT_RADIUS = 60;
+const DEFAULT_DIMENSION = 400;
+const VIEWPORT_BUFFER_MULTIPLIER = 0.5;
+const VIEWPORT_BUFFER_DIVISOR = 100;
