+
+  private tickTimer: ReturnType<typeof setInterval> | null = null;
+
+  constructor(props: MapBoxProps) {
+    super(props);
+
+    const { width, height, bounds, clusterer } = this.props;
+    const mercator = new WebMercatorViewport({
