});

test('handles very large bounds', () => {
  const largeBounds: [[number, number], [number, number]] = [
    [-179, -85],
    [179, 85],
  ];
  const props = {
    ...defaultProps,
    bounds: largeBounds,
  };

  const { container } = render(<MapBox {...props} />);
  expect(
